import {courses,MAX_FAILED_ATTEMPTS,score,fresh,normalise,completed,certificateEligible} from './content.js';
import {supabaseConfigured,getSupabase,emptyApp,loadRemoteApp,saveCourseProgress,saveTestRecord,emailsFromText} from './supabase-client.js';

const KEY='common-ground-training-v2';
let tick,state,app=emptyApp();
try{state=normalise(JSON.parse(localStorage.getItem(KEY)))}catch{state=fresh()}

const saveLocal=()=>localStorage.setItem(KEY,JSON.stringify(state));
const save=async c=>{saveLocal();if(c)await saveCourseProgress(app,c,state)};
const icon=n=>`<i class="ph-fill ph-${n}" aria-hidden="true"></i>`;
const button=(t,a,c='primary',x='',i='arrow-right')=>`<button class="${c}" data-action="${a}" ${x}>${icon(i)}<span>${t}</span></button>`;
const find=id=>courses.find(c=>c.id===id)||courses[0],cs=c=>state.courseStates[c.id],go=r=>location.hash===`#${r}`?render():location.hash=r;
const next=(c,s=cs(c))=>c.lessons.findIndex((_,i)=>!s.read.includes(i)),progress=(c,s=cs(c))=>`<progress max="${c.lessons.length}" value="${s.read.length}"></progress>`;
const status=(c,s=cs(c))=>completed(s,c)?'Completed & passed':s.read.length===c.lessons.length?'Final test ready':s.read.length?'In progress':'Ready to start';
const statusType=(c,s=cs(c),locked=false)=>locked?'access':completed(s,c)?'complete':s.read.length===c.lessons.length?'test':s.read.length?'progress':'start';
const statusIcon=t=>({access:'lock-simple',complete:'check-circle',test:'exam',progress:'clock',start:'play-circle'}[t]||'info');
const statusBadge=(c,s=cs(c),locked=false)=>{const t=statusType(c,s,locked);return `<span class="badge status-badge ${t}">${icon(statusIcon(t))}${locked?'Access required':status(c,s)}</span>`};
const metaPills=c=>`<div class="meta-pills"><span class="meta-pill sections">${icon('list-checks')}${c.lessons.length} sections</span><span class="meta-pill questions">${icon('question')}${c.questions.length} questions</span><span class="meta-pill time">${icon('timer')}${c.minutes}</span></div>`;
const moduleImages={
 teamwork:'teamwork.png',
 children:'parents-and-children-holding-hands.png',
 'building-children':'psychology.png',
 'older-people':'grandmother-using-a-walker.png',
 'problem-solving':'problem-solving.png',
 safeguarding:'protection-shield.png',
 'mental-health':'mental-health.png',
 inclusion:'size-diversity-hands.png',
 privacy:'protection-shield.png',
 'health-safety':'safety-vest.png',
 conflict:'conflict.png',
 'trauma-informed':'psychology.png',
 welcoming:'welcoming.png',
 wellbeing:'bandage.png'
};
const moduleImage=c=>`assets/module-cards/${moduleImages[c.id]||'teamwork.png'}`;
const authReady=()=>!supabaseConfigured||app.membership;
const userEmail=()=>app.user?.email||app.user?.user_metadata?.email||'Signed in';
const profileMenu=()=>`<details class="profile-menu"><summary aria-label="Open profile menu"><span class="avatar">${icon('user-circle')}</span><span>${userEmail()}</span>${icon('caret-down')}</summary><div class="profile-popover"><strong>${userEmail()}</strong><small>${app.organisation?.name||'No organisation yet'}${app.membership?.role?` · ${app.membership.role}`:''}</small>${app.membership?.role==='admin'?`<a href="#admin">${icon('users-three')}Admin area</a>`:''}<button class="secondary compact-btn" data-action="logout">${icon('sign-out')}<span>Sign out</span></button></div></details>`;
const card=c=>{const s=cs(c),locked=supabaseConfigured&&!authReady();return `<article class="course ${locked?'course-locked':''}"><div class="tile module-card-image"><img src="${moduleImage(c)}" alt="" loading="lazy">${statusBadge(c,s,locked)}</div><div class="course-body"><h3>${c.title}</h3><p>${c.description}</p>${metaPills(c)}${button(locked?'Create organisation account':s.read.length?'Continue course':'Open course',locked?'org-upgrade':`module/${c.id}`,'secondary','',locked?'buildings':'book-open-text')}</div></article>`};
const courseSection=(title,copy,list)=>`<div class="section-head"><div><h2>${title}</h2><p>${copy}</p></div><span class="badge status-badge start">${icon('stack')}${list.length} available</span></div><div class="cards">${list.map(card).join('')}</div>`;
const formMsg=()=>`${app.error?`<div class="notice error">${app.error}</div>`:''}${app.message?`<div class="notice success">${app.message}</div>`:''}`;

async function boot(){try{app=await loadRemoteApp();if(app.state)state=app.state}catch(err){app={...emptyApp(),error:'Could not connect to Supabase yet. You can still view this page, then retry sign in shortly.'};console.error(err)}saveLocal();render()}
function noOrgBar(){return supabaseConfigured&&app.user&&!app.membership?`<div class="invite-bar">${icon('warning-circle')}<span>You have not been invited by an organisation to take part in any training courses yet. Would you like to <a href="#org-upgrade">create an organisation account</a> to access training courses?</span></div>`:''}
function navLinks(r){return `<a href="#library" ${r==='library'?'aria-current="page"':''}>${icon('books')}Learn</a><a href="#progress" ${r==='progress'?'aria-current="page"':''}>${icon('chart-donut')}My progress</a><a href="#certificate" ${r==='certificate'?'aria-current="page"':''}>${icon('certificate')}Certificate</a>`}
function mobileMenu(r){return `<details class="mobile-nav"><summary aria-label="Open main menu">${icon('list')}</summary><div>${navLinks(r)}<a href="#about">${icon('info')}About this training</a><span class="mobile-menu-account"><strong>${userEmail()}</strong><small>${app.organisation?.name||'No organisation yet'}${app.membership?.role?` · ${app.membership.role}`:''}</small></span>${app.membership?.role==='admin'?`<a href="#admin" class="mobile-admin-link">${icon('users-three')}Admin area</a>`:''}<button class="secondary compact-btn" data-action="logout">${icon('sign-out')}<span>Sign out</span></button></div></details>`}
function shell(x,r){return `${noOrgBar()}<header><a class="brand" href="#library"><span class="brandmark">c</span> common ground</a><nav class="desktop-nav">${navLinks(r)}</nav>${mobileMenu(r)}${profileMenu()}</header><main id="main" tabindex="-1">${x}</main><footer><span>${supabaseConfigured?app.organisation?.name||'Supabase connected':'Local demo mode'}</span><span>${supabaseConfigured?'Saved to organisation account':'Saved on this browser only'}</span><a href="#about">About this training</a></footer>`}
function authShell(x){return `<main id="main" class="auth-main" tabindex="-1">${x}</main>`}
function landing(){return `<section class="landing"><div class="landing-hero"><a class="brand" href="#library"><span class="brandmark">c</span> common ground</a><span class="eyebrow">VOLUNTEER TRAINING</span><h1>Train volunteers to act with confidence, care and good judgement.</h1><p class="lead">Common Ground gives organisations a clear learning path for safer support, stronger teamwork, better boundaries and more thoughtful service.</p><div class="landing-points"><span>${icon('shield-check')}Safeguarding-aware</span><span>${icon('users-three')}Organisation-led</span><span>${icon('certificate')}Progress tracked</span></div></div><div class="landing-card auth-card"><span class="eyebrow">GET STARTED</span><h2>Access your training</h2><p>Sign in with an invited email, or create a new learner or organisation account.</p>${formMsg()}<form id="auth-form" data-kind="login"><label>Email<input name="email" type="email" required autocomplete="email"></label><label>Password<input name="password" type="password" required minlength="8" autocomplete="current-password"></label><button class="primary">${icon('sign-in')}Log in</button></form><div class="landing-actions">${button('Create learner account','signup','secondary','','user-plus')}${button('Create organisation','org-signup','secondary','','buildings')}</div><a href="#forgot-password">Forgot your password?</a></div></section>`}
function library(){if(supabaseConfigured&&!app.user)return landing();const core=courses.filter(c=>!c.advanced),advanced=courses.filter(c=>c.advanced);return `<div class="eyebrow">YOUR LEARNING SPACE</div><h1>Small lessons.<br><span>Stronger teamwork.</span></h1><p class="lead">Build practical skills for thoughtful, safe and proactive support.</p>${supabaseConfigured&&app.user&&!app.membership?waiting():''}${courseSection('Core courses',`${core.length} practical courses. One shared foundation.`,core)}${courseSection('Advanced courses','Deeper courses for volunteers taking on more complex, emotionally demanding or higher-risk situations.',advanced)}`}
function requireAccess(){return supabaseConfigured&&!authReady()}
function waiting(){return `<section class="panel access-panel"><span class="badge status-badge access">${icon('lock-simple')}Access required</span><h2>No active organisation yet</h2><p>Your account is signed in, but it is not connected to an organisation. Ask an organisation admin to invite your email address, or create an organisation account to start training now.</p>${button('Create organisation account','org-upgrade','primary','','buildings')}</section>`}
function gate(c){return requireAccess()?`<section class="narrow"><h1>${icon('lock-simple')}Organisation access required</h1><p>${app.user?'You are signed in, but you are not connected to an organisation yet. Create an organisation account or ask an existing organisation admin to invite you.':'Sign in with an invited account to start or continue course learning.'}</p>${app.user?button('Create organisation account','org-upgrade'):button('Log in','login')}</section>`:`<section class="narrow"><h1>Theory comes first</h1><p>Complete every section in order to unlock the test.</p>${button('Continue theory',`theory/${c.id}`)}</section>`}
function moduleView(c){if(requireAccess())return gate(c);const s=cs(c),ready=s.read.length===c.lessons.length,p=Math.round(s.read.length/c.lessons.length*100);return `<a class="back" href="#library">${icon('arrow-left')}All learning</a><div class="module-head">${statusBadge(c,s)}<h1>${c.title}</h1><p class="lead">${c.subtitle} ${c.description}</p><p>${c.minutes}, including reflection and the final test.</p>${button(ready?'Review theory':'Continue theory',ready?`lesson/${c.id}/0`:`theory/${c.id}`,'primary','','book-open-text')}</div><section class="module-progress"><div><strong>${p}% complete</strong><span>${s.read.length} of ${c.lessons.length} theory sections read</span></div>${progress(c,s)}</section><div class="notice"><strong>Apply your organisation’s procedures.</strong> General principles cannot replace local safeguarding or emergency training.</div><section class="panel test-panel"><div><span class="eyebrow">FINAL TEST</span><h2>${ready?'Ready when you are':'Complete the theory first'}</h2><p>${c.questions.length} questions · ${Math.round(c.testSeconds/60)} minutes · Pass with ${c.passMark} correct. ${MAX_FAILED_ATTEMPTS-s.failedAttempts} attempts remain.</p></div>${button(s.submitted?'View results':s.testStartedAt?'Continue test':'Take final test',s.submitted?`results/${c.id}`:s.testStartedAt?`assessment/${c.id}`:`test-ready/${c.id}`,'secondary',ready?'':'disabled','exam')}</section>`}
function lesson(c,i){if(requireAccess())return gate(c);const s=cs(c),n=next(c,s);if(n>=0&&i>n)i=n;s.lesson=i;state.active=c.id;save(c);const l=c.lessons[i],read=s.read.includes(i);return `<a class="back" href="#module/${c.id}">${icon('arrow-left')}Course overview</a><div class="reader-layout"><aside><p class="eyebrow">${c.title}</p><h2>Your learning path</h2>${progress(c,s)}<p>${s.read.length} of ${c.lessons.length} sections read</p><nav>${c.lessons.map((x,j)=>j<=Math.max(0,n)||s.read.includes(j)?`<a href="#lesson/${c.id}/${j}" ${i===j?'aria-current="step"':''}><span>${s.read.includes(j)?icon('check-circle'):j+1}</span>${x.title}</a>`:`<span class="locked-step">${icon('lock-simple')}${x.title}</span>`).join('')}</nav></aside><article class="reader"><div class="eyebrow">THEORY ${i+1} OF ${c.lessons.length} · ${l.time}</div><h1>${l.title}</h1><p class="intro">${l.intro}</p>${l.body.map(p=>`<p>${p}</p>`).join('')}<blockquote><span>${icon('lightbulb')}IN PRACTICE</span>${l.example}</blockquote><section class="reflection"><h2>${icon('brain')}Pause and reflect</h2><p>${l.reflect}</p><small>Think it through in your own words. There’s nothing to submit.</small></section><div class="actions">${read?button(i===c.lessons.length-1?'Go to final test':'Continue to next section',i===c.lessons.length-1?`test-ready/${c.id}`:`lesson/${c.id}/${i+1}`):button(i===c.lessons.length-1?'Mark as read & finish theory':'Mark as read & continue',`read/${c.id}/${i}`,'primary','','check-circle')}</div></article></div>`}
function ready(c){if(requireAccess())return gate(c);const s=cs(c);if(s.read.length<c.lessons.length)return gate(c);if(s.submitted)return results(c);return `<section class="narrow ready-card"><span class="eyebrow">THEORY COMPLETE</span><h1>${icon('exam')}Ready for your final test?</h1><p class="lead">${c.questions.length} questions, one at a time. The ${Math.round(c.testSeconds/60)}-minute timer starts when you begin.</p><div class="test-rules"><p><strong>Pass mark</strong><br>${c.passMark}/${c.questions.length}</p><p><strong>Time</strong><br>${Math.round(c.testSeconds/60)} minutes</p><p><strong>Attempts left</strong><br>${MAX_FAILED_ATTEMPTS-s.failedAttempts}</p></div><div class="notice">A second failed attempt resets this course’s theory.</div>${button('Begin final test',`start/${c.id}`,'primary','','play')}</section>`}
const remain=(c,s)=>s.testStartedAt?Math.max(0,c.testSeconds-Math.floor((Date.now()-s.testStartedAt)/1000)):c.testSeconds,clock=(c,s)=>`${String(Math.floor(remain(c,s)/60)).padStart(2,'0')}:${String(remain(c,s)%60).padStart(2,'0')}`;
function assessment(c){if(requireAccess())return gate(c);const s=cs(c);if(s.read.length<c.lessons.length)return gate(c);if(s.submitted)return results(c);if(!s.testStartedAt)return ready(c);const i=s.question,q=c.questions[i];return `<section class="narrow test-screen"><div class="test-top"><span class="eyebrow">QUESTION ${i+1} OF ${c.questions.length}</span><span class="timer" id="timer">${icon('timer')}${clock(c,s)}</span></div><div class="question-progress"><span style="width:${(i+1)/c.questions.length*100}%"></span></div><form id="question-form" data-course="${c.id}"><fieldset><legend>${q.q}</legend>${q.options.map((o,j)=>`<label class="option"><input type="radio" name="answer" value="${j}" ${s.answers[i]===j?'checked':''} required><span>${o}</span></label>`).join('')}</fieldset><button class="primary">${icon('arrow-right')}${i===c.questions.length-1?'Submit final test':'Next question'}</button></form></section>`}
async function finish(c,expired=false){const s=cs(c),n=score(s.answers,c),pass=n>=c.passMark;s.submitted=true;s.attempts++;s.testExpired=expired;s.testStartedAt=null;s.best=Math.max(s.best,n);s.records.push({score:n,passed:pass,completedAt:Date.now(),expired,attempt:s.attempts});if(!pass&&++s.failedAttempts>=MAX_FAILED_ATTEMPTS)s.read=[];saveLocal();await saveTestRecord(app,c,state,s.attempts,expired);go(`results/${c.id}`)}
function results(c){const s=cs(c),n=score(s.answers,c),pass=n>=c.passMark,locked=!pass&&s.failedAttempts>=MAX_FAILED_ATTEMPTS;return `<a class="back" href="#module/${c.id}">${icon('arrow-left')}Course overview</a><section class="narrow"><div class="result-head"><span class="badge status-badge ${pass?'complete':locked?'access':'test'}">${icon(pass?'check-circle':locked?'lock-simple':'arrow-clockwise')}${pass?'Passed':locked?'Theory reset required':'Retake available'}</span><div class="score">${n}<span> / ${c.questions.length}</span></div><h1>${pass?'Course complete':locked?'Return to the theory':'Review and try again'}</h1><div class="actions">${pass?button('Review course',`module/${c.id}`):locked?button('Restart theory',`theory/${c.id}`):button('Use my retake',`retry/${c.id}`)}${button('My progress','progress','secondary')}</div></div>${c.questions.map((q,i)=>`<article class="review ${s.answers[i]===q.answer?'correct':'incorrect'}"><span class="badge">${s.answers[i]===q.answer?'Correct':'Needs review'}</span><h3>${i+1}. ${q.q}</h3><p><strong>Your answer:</strong> ${s.answers[i]==null?'Not answered':q.options[s.answers[i]]}</p>${s.answers[i]!==q.answer?`<p><strong>Best response:</strong> ${q.options[q.answer]}</p>`:''}<p>${q.why}</p></article>`).join('')}</section>`}
function progressView(){if(requireAccess())return gate(courses[0]);const done=courses.filter(c=>completed(cs(c),c)).length,records=courses.flatMap(c=>cs(c).records.map(r=>({...r,c})));return `<div class="eyebrow">LEARNER PROFILE</div><h1>Your progress</h1><div class="stats"><div class="panel"><strong>${done} / ${courses.length}</strong><p>Courses completed</p></div><div class="panel"><strong>${courses.reduce((n,c)=>n+cs(c).read.length,0)} / ${courses.reduce((n,c)=>n+c.lessons.length,0)}</strong><p>Theory sections read</p></div><div class="panel"><strong>${records.length}</strong><p>Test records</p></div></div>${courses.map(c=>`<section class="panel">${statusBadge(c)}<h2>${c.title}</h2>${progress(c)}<p>${cs(c).read.length}/${c.lessons.length} sections · ${completed(cs(c),c)?'Test passed':'Test not passed'}</p>${button('Open course',`module/${c.id}`)}</section>`).join('')}<section class="panel"><h2>Test history</h2>${records.length?`<div class="history-list">${records.sort((a,b)=>b.completedAt-a.completedAt).map(r=>`<article><div><strong>${r.c.title} · ${r.passed?'Passed':'Not passed'}</strong><span>${new Date(r.completedAt).toLocaleString('en-GB')}</span></div><strong>${r.score}/${r.c.questions.length}</strong></article>`).join('')}</div>`:'<p>No tests submitted yet.</p>'}</section>`}
function certificate(){if(requireAccess())return gate(courses[0]);const ok=certificateEligible(state);return `<section class="narrow"><h1>${icon('certificate')}Foundation certificate</h1><div class="certificate"><span class="badge status-badge ${ok?'complete':'access'}">${icon(ok?'check-circle':'lock-simple')}${ok?'Eligible':'Locked'}</span><h2>Common Ground<br>Foundation Training</h2><strong>${courses.filter(c=>completed(cs(c),c)).length} of ${courses.length} courses passed</strong></div><ul class="requirements">${courses.map(c=>`<li><span>${c.title}</span><strong>${completed(cs(c),c)?'Passed':'Required'}</strong></li>`).join('')}</ul><button class="secondary" ${ok?'':'disabled'}>Download certificate</button></section>`}
function authForm(kind){const isOrg=kind==='org-signup',isSign=kind==='signup';return `<section class="auth-page"><a class="brand" href="#library"><span class="brandmark">c</span> common ground</a><div class="narrow auth-card"><span class="eyebrow">${isOrg?'ORGANISATION SETUP':isSign?'CREATE ACCOUNT':'WELCOME BACK'}</span><h1>${isOrg?'Create an organisation':isSign?'Create your learner account':'Log in'}</h1><p class="lead">${isOrg?'Create the first admin account for your organisation.':'Use the email address your organisation invited.'}</p>${formMsg()}<form id="auth-form" data-kind="${kind}">${isOrg?'<label>Organisation name<input name="organisation" required autocomplete="organization"></label>':''}<label>Email<input name="email" type="email" required autocomplete="email"></label><label>Password<input name="password" type="password" required minlength="8" autocomplete="${isSign||isOrg?'new-password':'current-password'}"></label><button class="primary">${icon(isOrg?'buildings':isSign?'user-plus':'sign-in')}${isOrg?'Create organisation':isSign?'Sign up':'Log in'}</button></form><p>${isSign?'Already have an account? <a href="#login">Log in</a>':'Need an account? <a href="#signup">Sign up</a>'} · <a href="#forgot-password">Forgot password?</a></p></div></section>`}
function forgot(){return `<section class="auth-page"><a class="brand" href="#library"><span class="brandmark">c</span> common ground</a><div class="narrow auth-card"><span class="eyebrow">PASSWORD RESET</span><h1>Forgot password</h1><p class="lead">Enter your email and Supabase will send a secure reset link.</p>${formMsg()}<form id="forgot-form"><label>Email<input name="email" type="email" required autocomplete="email"></label><button class="primary">${icon('paper-plane-tilt')}Send reset link</button></form></div></section>`}
function resetPassword(){return `<section class="auth-page"><a class="brand" href="#library"><span class="brandmark">c</span> common ground</a><div class="narrow auth-card"><span class="eyebrow">PASSWORD RESET</span><h1>Choose a new password</h1><p class="lead">After opening the reset email, set your new password here.</p>${formMsg()}<form id="reset-form"><label>New password<input name="password" type="password" required minlength="8" autocomplete="new-password"></label><button class="primary">${icon('lock-key')}Update password</button></form></div></section>`}
function orgUpgrade(){if(!app.user)return authForm('org-signup');return `<section class="narrow auth-card"><span class="eyebrow">ORGANISATION SETUP</span><h1>Create an organisation account</h1><p class="lead">Create an organisation and become its first admin. You can then access courses and invite learners.</p>${formMsg()}<form id="org-upgrade-form"><label>Organisation name<input name="organisation" required autocomplete="organization"></label><button class="primary">${icon('buildings')}Create organisation</button></form></section>`}
function invite(){return `<section class="auth-page"><a class="brand" href="#library"><span class="brandmark">c</span> common ground</a><div class="narrow auth-card"><span class="eyebrow">INVITATION</span><h1>Accept your invitation</h1><p class="lead">Use the invited email address to create or log in to your learner account. Once signed in, your organisation membership will unlock the courses.</p>${app.user?button('Go to learning','library'):`${button('Create learner account','signup')} ${button('Log in','login','secondary')}`}</div></section>`}
function invitees(){const rows=new Map();for(const i of app.invites||[])rows.set(i.email,{email:i.email,role:i.role,status:i.status==='accepted'?'active':i.status});for(const m of app.members||[]){const email=m.email||m.user_id;rows.set(email,{email,role:m.role,status:m.status==='active'?'active':m.status})}return [...rows.values()].sort((a,b)=>a.email.localeCompare(b.email))}
function admin(){if(!app.user)return authForm('login');if(app.membership?.role!=='admin')return `<section class="narrow"><h1>Admin access required</h1><p>Your account is not an organisation admin.</p></section>`;const people=invitees();return `<div class="eyebrow">ORGANISATION ADMIN</div><h1>${app.organisation?.name||'Organisation'} admin</h1>${formMsg()}<section class="panel admin-invite"><div><h2>${icon('user-plus')}Invite a learner</h2><p>Send one invite at a time so the list stays clear and each email can be checked before sending.</p></div><form id="invite-form"><label>Email address<input name="email" type="email" required autocomplete="email"></label><button class="primary">${icon('paper-plane-tilt')}Send invite</button></form></section><section class="panel"><h2>${icon('users-three')}Invitees</h2>${people.length?`<div class="invitee-list">${people.map(p=>`<article><div><strong>${p.email}</strong><span>${p.role}</span></div><span class="status-pill ${p.status}">${p.status}</span></article>`).join('')}</div>`:'<p>No learners invited yet.</p>'}</section>`}
function about(){return `<section class="narrow"><h1>About this training</h1><p>This general learning prototype does not replace organisational policy, professional advice or safeguarding training.</p><h2>Supabase setup</h2><p>Supabase mode uses email/password Auth, organisation memberships, invite records, RLS-protected progress rows and append-only test records. It avoids realtime, storage, polling and timer writes.</p>${button('Reset local demo progress','reset','secondary','','arrow-counter-clockwise')}</section>`}
function routeContent(r){const p=r.split('/'),c=find(p[1]);return p[0]==='module'?moduleView(c):p[0]==='lesson'?lesson(c,Number(p[2])||0):p[0]==='test-ready'?ready(c):p[0]==='assessment'?assessment(c):p[0]==='results'?results(c):p[0]==='org-signup'?authForm('org-signup'):p[0]==='signup'?authForm('signup'):p[0]==='login'?authForm('login'):p[0]==='forgot-password'?forgot():p[0]==='reset-password'?resetPassword():p[0]==='invite'?invite():p[0]==='org-upgrade'?orgUpgrade():({library,progress:progressView,certificate,admin,about}[r]||library)()}
function render(){clearInterval(tick);const r=location.hash.slice(1)||'library',authOnly=supabaseConfigured&&!app.user;document.getElementById('app').innerHTML=authOnly?authShell(routeContent(r)):shell(routeContent(r),r);document.getElementById('main').focus({preventScroll:true});scrollTo(0,0);const p=r.split('/'),c=find(p[1]),s=cs(c);if(p[0]==='assessment'&&s.testStartedAt&&!s.submitted)tick=setInterval(()=>{const e=document.getElementById('timer');if(!e)return clearInterval(tick);if(remain(c,s)<=0){clearInterval(tick);finish(c,true)}else e.innerHTML=icon('timer')+clock(c,s)},1000)}

async function refresh(message=''){app={...(await loadRemoteApp()),message};if(app.state)state=app.state;saveLocal();render()}
async function createOrg(name){const supabase=await getSupabase(),res=await supabase.from('organisations').insert({name,created_by:app.user.id});if(res.error)throw res.error;await refresh('Organisation created. You are the admin.');go('library')}
async function signupOrg(fd){const supabase=await getSupabase(),email=fd.get('email'),password=fd.get('password'),name=fd.get('organisation');const res=await supabase.auth.signUp({email,password,options:{emailRedirectTo:`${location.origin}${location.pathname}#library`}});if(res.error)throw res.error;if(!res.data.session){app.message='Check your email to confirm the organisation admin account.';render();return}app={...(await loadRemoteApp()),user:res.data.user,session:res.data.session};await createOrg(name)}
async function signup(fd){const supabase=await getSupabase(),res=await supabase.auth.signUp({email:fd.get('email'),password:fd.get('password'),options:{emailRedirectTo:`${location.origin}${location.pathname}#library`}});if(res.error)throw res.error;await refresh(res.data.session?'Signed in.':'Check your email to confirm your account.');go('library')}
async function login(fd){const supabase=await getSupabase(),res=await supabase.auth.signInWithPassword({email:fd.get('email'),password:fd.get('password')});if(res.error)throw res.error;await refresh('Signed in.');go('library')}
async function loadAdminLists(){if(!app.membership||app.membership.role!=='admin')return;const supabase=await getSupabase(),org=app.membership.organisation_id;const [m,i]=await Promise.all([supabase.from('organisation_members').select('user_id,role,status,profiles(email)').eq('organisation_id',org).order('created_at',{ascending:false}),supabase.from('organisation_invites').select('*').eq('organisation_id',org).order('created_at',{ascending:false})]);app.members=(m.data||[]).map(x=>({...x,email:x.profiles?.email}));app.invites=i.data||[]}

document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const p=b.dataset.action.split('/'),a=p[0],c=find(p[1]),s=cs(c);try{app.error='';app.message='';if(a==='logout'){const supabase=await getSupabase();if(supabase)await supabase.auth.signOut();app=emptyApp();state=fresh();saveLocal();go('library')}else if(a==='reset'){if(confirm('Reset all local progress?')){state=fresh();saveLocal();go('library')}}else if(a==='theory')go(`lesson/${c.id}/${Math.max(0,next(c,s))}`);else if(a==='read'){const i=Number(p[2]);if(!s.read.includes(i))s.read.push(i);s.read.sort((a,b)=>a-b);if(i===c.lessons.length-1&&s.failedAttempts>=2)s.failedAttempts=0;await save(c);go(i===c.lessons.length-1?`test-ready/${c.id}`:`lesson/${c.id}/${i+1}`)}else if(a==='start'){s.answers=Array(c.questions.length).fill(null);s.question=0;s.submitted=false;s.testStartedAt=Date.now();await save(c);go(`assessment/${c.id}`)}else if(a==='retry'){s.answers=Array(c.questions.length).fill(null);s.question=0;s.submitted=false;s.testStartedAt=null;await save(c);go(`test-ready/${c.id}`)}else go(b.dataset.action)}catch(err){app.error=err.message;render()}});
document.addEventListener('change',e=>{if(e.target.name==='answer'){const c=find(e.target.form.dataset.course);cs(c).answers[cs(c).question]=Number(e.target.value);save(c)}});
document.addEventListener('submit',async e=>{try{if(e.target.id==='question-form'){e.preventDefault();const c=find(e.target.dataset.course),s=cs(c);if(s.answers[s.question]==null)return;if(s.question<c.questions.length-1){s.question++;await save(c);render()}else await finish(c);return}if(e.target.id==='auth-form'){e.preventDefault();const kind=e.target.dataset.kind,fd=new FormData(e.target);if(!supabaseConfigured){app.error='Add the Supabase publishable key in supabase-config.js first.';render();return}if(kind==='org-signup')await signupOrg(fd);else if(kind==='signup')await signup(fd);else await login(fd);return}if(e.target.id==='forgot-form'){e.preventDefault();const supabase=await getSupabase();await supabase.auth.resetPasswordForEmail(new FormData(e.target).get('email'),{redirectTo:`${location.origin}${location.pathname}#reset-password`});app.message='If an account exists, a reset email has been sent.';render();return}if(e.target.id==='reset-form'){e.preventDefault();const supabase=await getSupabase(),res=await supabase.auth.updateUser({password:new FormData(e.target).get('password')});if(res.error)throw res.error;await refresh('Password updated.');return}if(e.target.id==='org-upgrade-form'){e.preventDefault();await createOrg(new FormData(e.target).get('organisation'));return}if(e.target.id==='invite-form'){e.preventDefault();const emails=emailsFromText(new FormData(e.target).get('email'));if(!emails.length){app.error='Add one valid email address.';render();return}if(emails.length>1){app.error='Send one invite at a time.';render();return}const supabase=await getSupabase();const res=await supabase.functions.invoke('invite-member',{body:{organisation_id:app.membership.organisation_id,emails,redirect_to:`${location.origin}${location.pathname}#invite`}});if(res.error)throw res.error;await loadAdminLists();app.message=`Queued ${emails.length} invite${emails.length===1?'':'s'}.`;render()}}catch(err){app.error=err.message;render()}});
addEventListener('hashchange',async()=>{if((location.hash==='#admin')&&app.membership?.role==='admin')await loadAdminLists();render()});
boot();
